            diff = nums[i] - nums[j]
            if -target <= diff <= target:
                # If we can reach j and jump to i
                if dp[j] != -1:
                    if dp[i] == -1 or dp[j] + 1 > dp[i]:
                        dp[i] = dp[j] + 1

